def dispatch_zone_jobs(entries, zone_code, submit):
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")
    if not isinstance(zone_code, str):
        raise TypeError("zone_code must be a string")
    if not zone_code:
        raise ValueError("zone_code must not be empty")
    if not callable(submit):
        raise TypeError("submit must be callable")

    for entry in entries:
        if not isinstance(entry, dict):
            raise TypeError("each entry must be a dictionary")
        if "identifier" not in entry or "location" not in entry:
            raise TypeError("entry is missing required fields")
        location = entry["location"]
        if not isinstance(location, dict) or "zone" not in location:
            raise TypeError("location must contain zone")
        if location["zone"] == zone_code:
            submit(entry)
    return True

